function say(id){const n=nodes[id];if(!n)return;$('#scene-label').textContent=n.scene;$('#time-label').textContent=n.time;$('#chapter-label').textContent=n.chapter;$('#speaker').textContent=n.speaker;$('#speaker-note').textContent=n.note;text.textContent=n.line;choices.innerHTML='';next.classList.remove('show');ending=!!n.ending;$('#character').classList.toggle('close',['kiss','continueyes','doorway','cuddle','love'].includes(id));if(id==='love'){shell.classList.add('intimate');setTimeout(()=>{shell.classList.remove('intimate');showEnding(nodes.love.ending)},2600);return}if(n.ending){showEnding(n.ending);return}n.choices.forEach(([label,sub,to,points])=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${label}<small>${sub}</small>`;b.onclick=()=>{affection=Math.min(10,affection+points);$('#meter-fill').style.width=(affection*10)+'%';$('#meter-value').textContent=affection;journal.push({scene:n.scene,line:label});say(to)};choices.append(b)})}
function showEnding(message){$('#speaker-note').textContent='AGE 27 · ARCHITECT';text.textContent=nodes[ending?'love':'dateagain'].ending?nodes[ending?'love':'dateagain'].line:text.textContent;choices.innerHTML=`<div class="end-card"><span class="end-kicker">✦ YOUR NIGHT, YOUR STORY</span><p>${message}</p><button class="primary-btn" id="replay-btn">PLAY AGAIN <span>↻</span></button></div>`;$('#replay-btn').onclick=()=>location.reload();next.classList.remove('show')}
// ending state needs the specific scene's ending copy, while keeping the final dialogue visible.
function finishNode(id){const n=nodes[id];ending=id;text.textContent=n.line;choices.innerHTML=`<div class="end-card"><span class="end-kicker">✦ YOUR NIGHT, YOUR STORY</span><p>${n.ending}</p><button class="primary-btn" id="replay-btn">PLAY AGAIN <span>↻</span></button></div>`;$('#replay-btn').onclick=()=>location.reload()}
$('#start-btn').onclick=()=>{player=$('#player-name').value.trim().slice(0,16)||'Alex';modal.innerHTML='<div class="eyebrow">A QUICK CHECK-IN</div><h2>Before the night begins</h2><p>This is a gentle romance for adults. All characters are 18+, intimacy is consensual and non-graphic, and you can choose to slow down or stop at any point.</p><button class="primary-btn" id="age-yes">I’M 18 OR OLDER — BEGIN <span>→</span></button><button class="close-btn" id="age-no">Not now</button>';overlay.hidden=false;$('#age-yes').onclick=()=>{overlay.hidden=true;title.style.display='none';started=true;say('meet')};$('#age-no').onclick=()=>overlay.hidden=true};
$('#journal-btn').onclick=()=>{modal.innerHTML=`<div class="eyebrow">THE LITTLE THINGS</div><h2>Your journal</h2>${journal.length?journal.map(x=>`<div class="journal-entry"><b>${x.scene}</b>${x.line}</div>`).join(''):'<p>Your night is just beginning. Little moments you choose will find their way here.</p>'}<button class="close-btn" id="close-journal">Close journal</button>`;overlay.hidden=false;$('#close-journal').onclick=()=>overlay.hidden=true};
$('#sound-btn').onclick=()=>{soundOn=!soundOn;$('#sound-btn').textContent=soundOn?'♫':'♪';toast(soundOn?'No soundtrack in this quiet build.':'Ambience off')};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1600)}
// Personalize only Riley's greeting so the player's chosen name feels part of the scene.
const originalSay=say; // dialogue remains intentionally name-neutral for replay-friendly pacing.

