25: function say(id){const n=nodes[id];if(!n)return;$('#scene-label').textContent=n.scene;$('#time-label').textContent=n.time;$('#chapter-label').textContent=n.chapter;$('#speaker').textContent=n.speaker;$('#speaker-note').textContent=n.note;text.textContent=n.line+(id==='meet'?` “I’m Riley, by the way. What should I call you?” You tell them ${player}.`: '');choices.innerHTML='';next.classList.remove('show');ending=!!n.ending;$('#character').classList.toggle('close',['kiss','continueyes','doorway','cuddle','love'].includes(id));if(id==='love'){shell.classList.add('intimate');setTimeout(()=>{shell.classList.remove('intimate');finishNode('love')},2600);return}if(n.ending){finishNode(id);return}n.choices.forEach(([label,sub,to,points])=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${label}<small>${sub}</small>`;b.onclick=()=>{affection=Math.min(10,affection+points);$('#meter-fill').style.width=(affection*10)+'%';$('#meter-value').textContent=affection;journal.push({scene:n.scene,line:label});say(to)};choices.append(b)})}
